"use client";

import { useState } from "react";
import Link from "next/link";

const products = [
  {
    name: "boAt Airdopes 141",
    type: "True Wireless Earbuds",
    image: "/products/earbuds.jpg",
    description:
      "Immersive sound with powerful bass."
  },

  {
    name: "boAt Nirvana 751 ANC",
    type: "Wireless Headphones",
    image: "/products/headphones.jpg",
    description:
      "Wireless headphones with active noise cancellation."
  },

  {
    name: "boAt Rockerz 255 Pro+",
    type: "Wireless Neckband",
    image: "/products/neckband.jpg",
    description:
      "Lightweight neckband for everyday listening."
  },

  {
    name: "boAt Wave Call",
    type: "Smart Watch",
    image: "/products/smartwatch.jpg",
    description:
      "Smartwatch with useful fitness features."
  }
];

function Navbar() {
  const [showProducts, setShowProducts] =
    useState(false);

  const [selectedProduct, setSelectedProduct] =
    useState(products[0]);

  return (
    <header className="navbar">

      <Link
        href="/"
        className="navbar-logo"
      >
        boAt
      </Link>

      <nav className="navbar-links">

        <div
          className="nav-product-menu"
          onMouseEnter={() =>
            setShowProducts(true)
          }
          onMouseLeave={() =>
            setShowProducts(false)
          }
        >

          <button className="nav-link">
            Products
          </button>

          {showProducts && (
            <div className="product-mega-menu">

              <div className="product-menu-list">

                <p className="menu-title">
                  Popular Products
                </p>

                {products.map((product) => (
                  <button
                    key={product.name}
                    className="product-menu-item"
                    onMouseEnter={() =>
                      setSelectedProduct(product)
                    }
                  >

                    <img
                      src={product.image}
                      alt=""
                    />

                    <span>
                      <strong>
                        {product.name}
                      </strong>

                      <small>
                        {product.type}
                      </small>
                    </span>

                  </button>
                ))}

                <Link
                  href="/products"
                  className="menu-view-all"
                >
                  View all products →
                </Link>

              </div>

              <div className="product-menu-info">

                <img
                  src={selectedProduct.image}
                  alt={selectedProduct.name}
                />

                <p className="eyebrow">
                  PRODUCT INFORMATION
                </p>

                <h3>
                  {selectedProduct.name}
                </h3>

                <p>
                  {selectedProduct.type}
                </p>

                <small>
                  {selectedProduct.description}
                </small>

                <Link
                  href="/products"
                  className="button small-button"
                >
                  Explore Now
                </Link>

              </div>

            </div>
          )}

        </div>

        <Link href="/warranty">
          Your Devices
        </Link>

        <Link href="/help">
          Help Topics
        </Link>

      </nav>

      <Link
        href="/contact"
        className="nav-button"
      >
        Connect with us
      </Link>

    </header>
  );
}

export default Navbar;